var response = await client.Products.GetProductAsync(101);
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var product = (IReadOnlyDictionary<string, object?>)body["product"]!;
var pricingAndStock = (IReadOnlyDictionary<string, object?>)product["product_pricing_and_stock"]!;
Console.WriteLine($"{product["name"]} {product["sku"]} {product["base_price"]} {pricingAndStock["available_stock"]}");

